// Original procedural soundtrack and effects; no external audio files or services.
export class Audio{
 constructor(){this.enabled=true;this.music=false;this.volume=.18;this.ctx=null;this.lastShot=0;this.note=0;this.musicTimer=null;}
 start(){if(!this.ctx){const Context=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Context)return;this.ctx=new Context();this.master=this.ctx.createGain();this.master.gain.value=this.volume;this.master.connect(this.ctx.destination);}this.ctx.resume();}
 tone(frequency,duration=.15,type='sine',gain=.2,slide=1,delay=0){if(!this.ctx||!this.enabled)return;const start=this.ctx.currentTime+delay,osc=this.ctx.createOscillator(),amp=this.ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(frequency,start);osc.frequency.exponentialRampToValueAtTime(Math.max(20,frequency*slide),start+duration);amp.gain.setValueAtTime(.001,start);amp.gain.exponentialRampToValueAtTime(Math.max(.001,gain),start+.008);amp.gain.exponentialRampToValueAtTime(.001,start+duration);osc.connect(amp);amp.connect(this.master);osc.start(start);osc.stop(start+duration+.02);}
 noise(duration=.12,gain=.13,frequency=1000){if(!this.ctx||!this.enabled)return;const len=Math.floor(this.ctx.sampleRate*duration),buffer=this.ctx.createBuffer(1,len,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<len;i++)data[i]=(Math.random()*2-1)*(1-i/len);const src=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),amp=this.ctx.createGain();src.buffer=buffer;filter.type='lowpass';filter.frequency.value=frequency;amp.gain.value=gain;src.connect(filter);filter.connect(amp);amp.connect(this.master);src.start();}
 play(event){if(!this.ctx||!this.enabled)return;switch(event.type){case 'attack':{const now=this.ctx.currentTime;if(now-this.lastShot<.09)return;this.lastShot=now;const frequencies={fire:130,nature:370,earth:85,light:780,darkness:190,water:540,composite:250};this.tone(frequencies[event.element]||250,.12,event.element==='light'?'sine':'triangle',.1,.6);if(['fire','earth'].includes(event.element))this.noise(.08,.12,700);break;}case 'build':this.tone(220,.12,'triangle',.3);this.tone(330,.16,'triangle',.3,1,.08);break;case 'upgrade':case 'unlock':[330,440,660].forEach((f,i)=>this.tone(f,.25,'triangle',.25,1,i*.08));break;case 'wave':this.tone(110,.4,'sawtooth',.18);this.tone(165,.3,'triangle',.2,1,.15);break;case 'boss':this.tone(65,.8,'sawtooth',.2);this.tone(98,.8,'triangle',.2,1,.1);break;case 'leak':this.tone(180,.25,'square',.15,.5);break;case 'clear':this.tone(523,.3,'triangle',.2);this.tone(784,.3,'triangle',.2,1,.13);break;case 'cast':this.noise(.35,.18,2500);this.tone(550,.4,'sine',.2,2);break;case 'defeat':[330,277,220,165].forEach((f,i)=>this.tone(f,.4,'triangle',.2,1,i*.17));break;}}
 setMusic(on){this.music=on;if(this.musicTimer)clearInterval(this.musicTimer);if(on){const melody=[0,7,12,10,7,3,5,7,0,7,12,15,12,10,7,3];this.musicTimer=setInterval(()=>{if(!this.ctx||!this.music)return;const n=melody[this.note++%melody.length];this.tone(130.81*2**(n/12),.65,'triangle',.055);if(this.note%4===1)this.tone(65.405,.9,'sine',.06);},450);}}
}
